-- Generated by tools/content/build_content.py: every object model in the game that isn't a
-- curated piece, one piece each. Only used with PlayerHousing.Catalog = everything; safe to
-- apply either way (the module leaves these pieces out otherwise).

DELETE FROM `mod_playerhousing_piece_rule` WHERE `item_entry` BETWEEN 940000 AND 944999;
DELETE FROM `mod_playerhousing_piece` WHERE `item_entry` BETWEEN 940000 AND 944999;
DELETE FROM `item_template` WHERE `entry` BETWEEN 940000 AND 944999;
DELETE FROM `gameobject_template` WHERE `entry` BETWEEN 950000 AND 954999;
















-- Ghosts: see-through copies of the pieces, for placing and moving them (the client patch
-- adds the same models and displays to the client).
DELETE FROM `creaturedisplayinfo_dbc` WHERE `ID` BETWEEN 100000 AND 104999;
DELETE FROM `creaturemodeldata_dbc` WHERE `ID` BETWEEN 100000 AND 104999;
DELETE FROM `creature_model_info` WHERE `DisplayID` BETWEEN 100000 AND 104999;
